package com.grapefruit.hellblazer.client.outfit;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeDeformation;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * The specialist's clothes as armour meshes (generated by tools/gen_outfit.py - edit that, not this). Each is a full
 * humanoid (head, hat, body, arms, legs, as HumanoidModel wants) with only the pieces that piece of clothing covers:
 * the coat's skirts hang from the legs so they swing with each step.
 */
public final class OutfitModels {
    private OutfitModels() {}

    /** The trench coat, open over the shirt and tie (both cuts of sleeve: CoatModel shows one). */
    public static LayerDefinition coat() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        PartDefinition g_head = root.addOrReplaceChild("head", CubeListBuilder.create()

                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_hat = root.addOrReplaceChild("hat", CubeListBuilder.create()

                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_body = root.addOrReplaceChild("body", CubeListBuilder.create()
                .texOffs(0, 0).addBox(-4.0F, -0.0F, -2.0F, 8.0F, 12.0F, 4.0F, new CubeDeformation(0.62F))   // torso
                .texOffs(24, 34).addBox(-4.625F, -2.0F, 2.0F, 9.25F, 2.625F, 1.0F)   // collar_back
                .texOffs(0, 34).addBox(3.625F, -1.625F, -0.375F, 1.0F, 2.25F, 3.375F)   // collar_side_l
                .texOffs(10, 34).addBox(-4.625F, -1.625F, -0.375F, 1.0F, 2.25F, 3.375F)   // collar_side_r
                .texOffs(20, 34).addBox(-4.875F, 8.5F, -2.5F, 1.0F, 4.25F, 0.5F)   // belt_end
                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_right_arm = root.addOrReplaceChild("right_arm", CubeListBuilder.create()

                , PartPose.offset(-5.0F, 2.0F, -0.0F));
        PartDefinition g_left_arm = root.addOrReplaceChild("left_arm", CubeListBuilder.create()

                , PartPose.offset(5.0F, 2.0F, -0.0F));
        PartDefinition g_right_sleeve = g_right_arm.addOrReplaceChild("right_sleeve", CubeListBuilder.create()
                .texOffs(25, 0).addBox(-3.0F, -2.0F, -2.0F, 4.0F, 12.0F, 4.0F, new CubeDeformation(0.5F))   // sleeve_r
                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_left_sleeve = g_left_arm.addOrReplaceChild("left_sleeve", CubeListBuilder.create()
                .texOffs(42, 0).addBox(-1.0F, -2.0F, -2.0F, 4.0F, 12.0F, 4.0F, new CubeDeformation(0.5F))   // sleeve_l
                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_right_sleeve_slim = g_right_arm.addOrReplaceChild("right_sleeve_slim", CubeListBuilder.create()
                .texOffs(0, 17).addBox(-2.0F, -2.0F, -2.0F, 3.0F, 12.0F, 4.0F, new CubeDeformation(0.5F))   // slimsleeve_r
                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_left_sleeve_slim = g_left_arm.addOrReplaceChild("left_sleeve_slim", CubeListBuilder.create()
                .texOffs(15, 17).addBox(-1.0F, -2.0F, -2.0F, 3.0F, 12.0F, 4.0F, new CubeDeformation(0.5F))   // slimsleeve_l
                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_right_leg = root.addOrReplaceChild("right_leg", CubeListBuilder.create()

                , PartPose.offset(-1.9F, 12.0F, -0.0F));
        PartDefinition g_left_leg = root.addOrReplaceChild("left_leg", CubeListBuilder.create()

                , PartPose.offset(1.9F, 12.0F, -0.0F));
        PartDefinition g_right_skirt = g_right_leg.addOrReplaceChild("right_skirt", CubeListBuilder.create()
                .texOffs(30, 17).addBox(-2.0F, -0.0F, -2.0F, 4.0F, 8.0F, 4.0F, new CubeDeformation(0.78F))   // skirt_r
                , PartPose.offsetAndRotation(0.0F, -0.0F, -0.0F, 0.0F, -0.0F, 0.05F));
        PartDefinition g_left_skirt = g_left_leg.addOrReplaceChild("left_skirt", CubeListBuilder.create()
                .texOffs(47, 17).addBox(-2.0F, -0.0F, -2.0F, 4.0F, 8.0F, 4.0F, new CubeDeformation(0.78F))   // skirt_l
                , PartPose.offsetAndRotation(0.0F, -0.0F, -0.0F, 0.0F, -0.0F, -0.05F));
        return LayerDefinition.create(mesh, 64, 64);
    }

    /** The black trousers and belt. */
    public static LayerDefinition trousers() {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        PartDefinition g_head = root.addOrReplaceChild("head", CubeListBuilder.create()

                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_hat = root.addOrReplaceChild("hat", CubeListBuilder.create()

                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_body = root.addOrReplaceChild("body", CubeListBuilder.create()
                .texOffs(0, 0).addBox(-4.0F, -0.0F, -2.0F, 8.0F, 12.0F, 4.0F, new CubeDeformation(0.34F))   // waist
                , PartPose.offset(0.0F, -0.0F, -0.0F));
        PartDefinition g_right_arm = root.addOrReplaceChild("right_arm", CubeListBuilder.create()

                , PartPose.offset(-5.0F, 2.0F, -0.0F));
        PartDefinition g_left_arm = root.addOrReplaceChild("left_arm", CubeListBuilder.create()

                , PartPose.offset(5.0F, 2.0F, -0.0F));
        PartDefinition g_right_leg = root.addOrReplaceChild("right_leg", CubeListBuilder.create()
                .texOffs(25, 0).addBox(-2.0F, -0.0F, -2.0F, 4.0F, 12.0F, 4.0F, new CubeDeformation(0.32F))   // leg_r
                , PartPose.offset(-1.9F, 12.0F, -0.0F));
        PartDefinition g_left_leg = root.addOrReplaceChild("left_leg", CubeListBuilder.create()
                .texOffs(42, 0).addBox(-2.0F, -0.0F, -2.0F, 4.0F, 12.0F, 4.0F, new CubeDeformation(0.32F))   // leg_l
                , PartPose.offset(1.9F, 12.0F, -0.0F));
        return LayerDefinition.create(mesh, 64, 32);
    }
}
